def native(x):
    if isinstance(x,np.generic): return x.item()
    if isinstance(x,np.ndarray): return x.tolist()
    if isinstance(x,dict): return {k:native(v) for k,v in x.items()}
    if isinstance(x,(tuple,list)): return [native(v) for v in x]
    return x
def dump(name,obj): OUT.mkdir(parents=True,exist_ok=True); (OUT/name).write_text(json.dumps(native(obj),indent=2,sort_keys=True)+'\n')
def save(name,**kw): OUT.mkdir(parents=True,exist_ok=True); np.savez_compressed(OUT/name,**kw)
